// Shipping demand forecast. Generated by the report engine over historical
// shipment data; the dispatch service uses it to size pickup capacity.

import { z } from '../lib/validate';

export const ForecastSchema = z.object({
  id: z.string().min(1),
  customerId: z.string().min(1).optional(),
  scope: z.enum(['platform', 'customer', 'carrier']),
  carrierId: z.string().min(1).optional(),
  periodStart: z.number().int().nonnegative(),
  periodEnd: z.number().int().nonnegative(),
  expectedShipments: z.number().int().nonnegative(),
  expectedWeightG: z.number().nonnegative(),
  confidence: z.number().min(0).max(1),
  metadata: z.record(z.string()).default({}),
  generatedAt: z.number().int().nonnegative(),
});

export type Forecast = z.infer<typeof ForecastSchema>;

export function parseForecast(value: unknown): Forecast {
  return ForecastSchema.parse(value);
}

export function forecastDurationMs(forecast: Forecast): number {
  return forecast.periodEnd - forecast.periodStart;
}
